create table public.fiscalization_guides (
  id uuid primary key default gen_random_uuid(),
  category text not null,
  title text not null,
  summary text not null default '',
  content text not null,
  source_note text not null default '',
  reference_url text,
  image_paths text[] not null default '{}',
  sort_order integer not null default 100,
  created_by uuid references auth.users(id),
  updated_by uuid references auth.users(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint fiscalization_guides_title_nonempty check (length(btrim(title)) > 0),
  constraint fiscalization_guides_category_title_unique unique (category, title),
  constraint fiscalization_guides_content_nonempty check (length(btrim(content)) > 0),
  constraint fiscalization_guides_image_limit check (cardinality(image_paths) <= 8)
);

alter table public.fiscalization_guides enable row level security;
grant select, insert, update, delete on public.fiscalization_guides to authenticated;

create policy fiscalization_guides_read_staff
  on public.fiscalization_guides for select to authenticated
  using (public.can_use_app() or public.is_admin());
create policy fiscalization_guides_admin_insert
  on public.fiscalization_guides for insert to authenticated
  with check (public.is_admin() and created_by = (select auth.uid()) and updated_by = (select auth.uid()));
create policy fiscalization_guides_admin_update
  on public.fiscalization_guides for update to authenticated
  using (public.is_admin())
  with check (public.is_admin() and updated_by = (select auth.uid()));
create policy fiscalization_guides_admin_delete
  on public.fiscalization_guides for delete to authenticated
  using (public.is_admin());

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('fiscalization-guides', 'fiscalization-guides', false, 8388608, array['image/jpeg','image/png','image/webp'])
on conflict (id) do update
set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

create policy fiscalization_guides_storage_read
  on storage.objects for select to authenticated
  using (bucket_id = 'fiscalization-guides' and (public.can_use_app() or public.is_admin()));
create policy fiscalization_guides_storage_insert
  on storage.objects for insert to authenticated
  with check (bucket_id = 'fiscalization-guides' and public.is_admin());
create policy fiscalization_guides_storage_update
  on storage.objects for update to authenticated
  using (bucket_id = 'fiscalization-guides' and public.is_admin())
  with check (bucket_id = 'fiscalization-guides' and public.is_admin());
create policy fiscalization_guides_storage_delete
  on storage.objects for delete to authenticated
  using (bucket_id = 'fiscalization-guides' and public.is_admin());

insert into public.fiscalization_guides (category,title,summary,content,source_note,reference_url,sort_order)
values
('Segurança de crianças','Dispositivos de retenção infantil — referência do material recebido','Resumo da imagem sobre o art. 168 do CTB: bebê conforto, cadeira, assento de elevação e cinto conforme idade e porte.','O material recebido relaciona quatro situações: bebê conforto (até 1 ano e de 9 a 13 kg; de costas para o para-brisa no banco traseiro); cadeira de segurança (de 1 a 4 anos e de 9 a 18 kg; de frente para o para-brisa, presa pelo cinto); assento de elevação/booster (de 4 a 7 anos e meio e de 18 a 36 kg; de frente para o para-brisa com cinto de três pontos); e somente cinto para maiores de 7 anos e meio, acima de 36 kg e 1,50 m. A imagem atribui a orientação ao art. 168 do CTB.','Transcrição de imagem fornecida pela equipe em 28/10/2026. Idades, pesos e regras devem ser conferidos na norma vigente antes de uso.','https://www.planalto.gov.br/ccivil_03/leis/l9503compilado.htm',10),
('Classificação de veículos','Bicicleta elétrica, equipamento de mobilidade e ciclomotor','Quadro comparativo de potência, velocidade, acelerador e exigências mostrado no material enviado.','O quadro recebido indica: bicicleta elétrica — até 1.000 W, até 32 km/h, sem acelerador e sem CRLV/ACC/CNH/capacete; equipamento de mobilidade — até 1.000 W, até 32 km/h, com acelerador e sem CRLV/ACC/capacete; ciclomotor — até 4.000 W (ou 50 cc), até 50 km/h, com acelerador e com CRLV/ACC/CNH/capacete; motoneta ou motocicleta — acima de 4.000 W (ou 50 cc) ou acima de 50 km/h, com acelerador e com CRLV/CNH/capacete.','Transcrição resumida de imagem recebida. Confirmar a classificação e os requisitos na Resolução CONTRAN vigente.','https://www.gov.br/transportes/pt-br/assuntos/transito/conteudo-contran/resolucoes/Resolucao9962023.pdf',20),
('Classificação de veículos','Equipamento autopropelido e bicicleta motorizada','Notas de campo sobre enquadramento por características construtivas, potência e velocidade.','O material recebido orienta avaliar as características técnicas do equipamento, incluindo potência, velocidade máxima, acelerador, forma de propulsão e dimensões, para distinguir equipamento de mobilidade individual autopropelido, ciclomotor e motocicleta. A nota destaca que bicicletas motorizadas/artesanais podem exigir registro conforme sua classificação. Não concluir enquadramento somente pelo nome comercial ou aparência: conferir dados técnicos e a regulamentação vigente.','Transcrição resumida de imagem e anotação. Confirmar na Resolução CONTRAN vigente; conteúdo não substitui consulta oficial.','https://www.gov.br/transportes/pt-br/assuntos/transito/conteudo-contran/resolucoes/Resolucao9962023.pdf',21),
('Veículos de carga','Calendário de circulação — veículos registrados como caminhão','Calendário ilustrado de final de placa para caminhões constante no material enviado.','A imagem recebida associa os finais de placa ao mês: setembro — 1 e 2; outubro — 3, 4 e 5; novembro — 6, 7 e 8; dezembro — 9 e 0. A imagem não informa, por si só, abrangência, ano de validade ou condições completas. Confirmar a regra local e a vigência antes de orientar ou fiscalizar.','Transcrição parcial de imagem. Aplicabilidade e validade não identificadas no arquivo recebido; confirmar com fonte oficial local.','',30),
('Veículos de carga','Calendário ilustrado — ônibus, reboques e semirreboques','Segundo quadro visual recebido, separado do quadro de caminhões.','A imagem recebida associa os finais de placa ao mês: julho — 1 e 2; agosto — 3 e 4; setembro — 5 e 6; outubro — 7 e 8; novembro — 9; dezembro — 0. O recorte não informa abrangência, ano de validade ou condições completas. Confirmar com a norma ou autoridade competente antes de usar.','Transcrição parcial. O material não identifica a jurisdição nem o período de validade.','',31),
('Motocicletas','Itens de fiscalização de motocicletas indicados no quadro','Lista visual de equipamentos e condições apontados no material recebido.','O quadro recebido menciona: selo INMETRO do capacete; elementos retrorrefletivos; viseira ou óculos de proteção; transporte de criança; manobras de equilíbrio em uma roda; dispositivo catadióptrico; rabeta; placa sem visibilidade/legibilidade e acessórios; redutor de temperatura; descarga livre; pneus; retrovisores; farol apagado; lâmpada LED; e motofrete/mototáxi. A imagem cita artigos e resoluções em alguns itens, mas a leitura é parcial.','Transcrição de quadro ilustrado; artigos, exigências e medidas não foram validados. Conferir CTB, MBFT e resoluções vigentes.','https://www.planalto.gov.br/ccivil_03/leis/l9503compilado.htm',40),
('Motocicletas','Escape e silenciador — códigos exibidos no resumo recebido','Resumo de códigos e descrições vistos em imagens de material de fiscalização.','O material recebido mostra, entre outros, os enquadramentos 663-71 (veículo sem equipamento obrigatório), 665-31 (descarga livre), 665-32 (silenciador defeituoso, deficiente ou inoperante) e 664-50 (equipamento obrigatório em desacordo). As imagens também citam medidas administrativas e observações específicas. Verifique o código, a tipificação e a medida no MBFT vigente para a situação concreta; este resumo não define o enquadramento.','Transcrição de material interno/imagens; duplicatas visuais foram consolidadas. Conferir o MBFT oficial vigente.','https://www.gov.br/transportes/pt-br/assuntos/transito/conteudo-contran/resolucoes/Resolucao9852022.pdf',41),
('Combinação de veículos','Autuação em combinação de veículos','Orientação de procedimento apresentada em anotação recebida.','A anotação recebida recomenda, nas infrações de circulação, priorizar a unidade tratora; se não for possível identificá-la, registrar a unidade tracionada e consignar a combinação nas observações. Para irregularidade relacionada às condições da própria unidade, a anotação recomenda avaliar cada unidade irregular. Para estacionamento, aponta a placa da unidade tratora, salvo situações de desacoplamento. Confirmar a orientação no MBFT e nas normas vigentes antes de aplicar.','Transcrição de anotação interna, sem validação normativa nesta ficha.','',50),
('Procedimentos','Boa ordem administrativa','Trecho recebido sobre prevenção da repetição da conduta e segurança viária.','A anotação recebida descreve a boa ordem administrativa como medida a avaliar quando, embora a irregularidade tenha cessado durante a abordagem, ainda seja necessário garantir que a conduta não se repita, considerando proteção à vida, segurança viária e integridade física. A imagem cita como exemplos os arts. 173, 174, 175, 210, 230, I, 231, VIII, 239, 253 e 253-A do CTB. Avaliar cada caso conforme a lei e os procedimentos oficiais atuais.','Transcrição de material fornecido. Não constitui orientação jurídica; confirmar hipóteses e medidas no CTB/MBFT vigentes.','https://www.planalto.gov.br/ccivil_03/leis/l9503compilado.htm',60),
('Veículos','Alteração de característica do veículo','Resumo do trecho do art. 98 do CTB mostrado em imagem.','O material recebido reproduz a regra de que proprietário ou responsável não deve modificar características de fábrica sem autorização prévia da autoridade competente. Também menciona que veículos e motores alterados devem atender aos limites e exigências ambientais aplicáveis. Conferir a redação legal atual e as regras específicas para a modificação analisada.','Transcrição resumida; conferir texto legal e regulamentação complementar vigentes.','https://www.planalto.gov.br/ccivil_03/leis/l9503compilado.htm',61),
('Procedimentos','Recusa ao teste do etilômetro — anotação recebida','Resumo de uma anotação de treinamento; conferir cada hipótese e procedimento.','A anotação recebida distingue a recusa ao teste (art. 165-A) da condução sob influência de álcool (art. 165), conforme sinais e constatação. O texto também alerta para não registrar simultaneamente os dois enquadramentos para a mesma pessoa na mesma fiscalização. A imagem apresenta exemplos, mas eles não substituem a análise do caso, os procedimentos de constatação nem o MBFT vigente.','Transcrição de anotação interna; confirmar requisitos e procedimentos oficiais antes de utilizar.','https://www.planalto.gov.br/ccivil_03/leis/l9503compilado.htm',70),
('Veículos de carga','Excesso de carga e transbordo','Resumo do trecho recebido sobre transbordo de carga excedente.','O material recebido descreve o transbordo como retirada ou remanejamento da carga que ultrapassa limites de peso ou capacidade, às expensas do responsável, sem prejuízo da autuação cabível. Menciona avaliação de segurança para produtos perigosos, perecíveis, cargas vivas e passageiros e possível recolhimento quando o transbordo não for dispensado. Confirmar limites, procedimento e competência na norma vigente.','Transcrição resumida de material interno; conferir CTB e MBFT atuais.','https://www.planalto.gov.br/ccivil_03/leis/l9503compilado.htm',71),
('Documentos e remoção','Recolhimento de documentos físicos — anotação para conferência','A própria imagem apresenta afirmação sobre a Resolução CONTRAN 623/2016; validar antes de aplicar.','A anotação recebida afirma que não há recolhimento de documentos físicos em certas situações e menciona a Resolução CONTRAN 623/2016 e o TRV. O recorte não permite confirmar o alcance, as exceções ou a vigência dessa orientação. Não aplicar como regra sem conferir a legislação atual e o procedimento do órgão.','Conteúdo transcrito com baixa confiança normativa; consulta oficial obrigatória.','https://www.gov.br/transportes/pt-br/assuntos/transito/conteudo-contran/resolucoes',80),
('Iluminação e segurança','Sistema de iluminação — parecer CETRAN recebido','Resumo de parecer datado de 30/07/2024 apresentado em imagem.','O material recebido diferencia sistema de iluminação simplesmente apagado de sistema ineficiente ou inoperante e sugere avaliar o enquadramento e a necessidade de remoção considerando as condições de segurança. A imagem cita art. 230, IX, do CTB e resolução do CONTRAN. Confirme o parecer integral, sua aplicabilidade e a legislação vigente antes de utilizar.','Transcrição resumida de parecer mostrado em imagem; São Paulo, 30/07/2024.','https://www.planalto.gov.br/ccivil_03/leis/l9503compilado.htm',81),
('Veículos','Enquadramentos 1000/1001 — anotação interna não validada','Lista de códigos descrita na imagem como “enquadramentos fictícios”.','O material recebido lista: 1000-1 para busca e apreensão; 1000-2 para Renajud/circulação; 1001-1 para veículo abandonado; 1001-2 para veículo em sinistro. A própria imagem usa o termo “enquadramentos fictícios”; portanto, não trate esses números como códigos oficiais sem confirmação formal do órgão competente.','Transcrição de referência interna de baixa confiança; validar códigos e competência antes de qualquer uso.','',90),
('Veículos','Veículo de leilão — conferência antes de providências','Anotação de áudio/transcrição exibida no material recebido.','A transcrição recebida recomenda confirmar se o veículo é realmente proveniente de leilão e conferir gravações de motor, documentação e situação registral antes de qualquer providência. A própria anotação alerta que “caráter geral” não deve ser confundido com leilão. Verifique cada informação em fontes e procedimentos oficiais.','Transcrição de anotação interna; não substitui consulta documental nem procedimento oficial.','',91),
('Veículos','Veículo sem placa — campos de identificação em AIT','Resumo visual de tela de preenchimento de auto de infração.','A imagem mostra um formulário de identificação do veículo com opção de informar placa ou chassi, além de marca, espécie e cor. O exemplo exibe “SEMCHASSI” como texto de preenchimento; não o utilize como dado real. Consulte o procedimento oficial do sistema e preencha apenas informações verificadas.','Transcrição de captura de tela; o exemplo não deve ser tratado como regra ou dado real.','',92),
('Veículos de carga','Tratores agrícolas e máquinas — resumo para conferência','Imagem extensa com condições de registro, circulação, habilitação e dimensões.','A imagem recebida reúne observações sobre RENAGRO, registro/placa, circulação em via pública, CNH e dimensões de tratores, máquinas agrícolas, retroescavadeiras, empilhadeiras e implementos. O texto é extenso e a imagem reduzida não permite validar todos os limites e exceções. Consulte a Resolução CONTRAN e as normas atuais para o tipo de equipamento e situação concretos.','Transcrição resumida por legibilidade limitada; confirmar cada regra em fonte oficial.','https://www.gov.br/transportes/pt-br/assuntos/transito/conteudo-contran/resolucoes',100),
('Veículos','Parada obrigatória e desobediência a sinalização','Discussão interna recebida sobre diferenciação entre condutas.','A imagem registra uma conversa comparando sinal de parada obrigatória e desobediência a sinalização, com menções aos arts. 208 e 195 do CTB. O diálogo não estabelece conclusão normativa completa. Identifique o sinal, a conduta observada e consulte o CTB/MBFT vigente antes de escolher o enquadramento.','Transcrição de conversa de equipe; conteúdo não validado como orientação oficial.','https://www.planalto.gov.br/ccivil_03/leis/l9503compilado.htm',110),
('Equipamentos','Etilômetro — identificação do equipamento mostrado','Dados visíveis na etiqueta fotografada; confirmar patrimônio e calibração localmente.','A imagem mostra a identificação “Etilômetro 5ª cia”, número de série F-000047-22, SN 085357 e ano de fabricação 2008. Confirmar os dados no inventário e verificar validade de verificação metrológica antes do uso operacional.','Transcrição de fotografia enviada; dado de inventário deve ser conferido pela unidade responsável.','',120),
('Fiscalização','Orientações gerais de vistoria de veículos elétricos e equipamentos','Notas extensas de consulta sobre enquadramento de equipamentos de mobilidade.','O material recebido orienta registrar características observadas e consultar potência, velocidade máxima, propulsão, presença de acelerador e documentação para a classificação do equipamento. Evite concluir somente pela aparência; documente os elementos verificados e confirme a regra vigente.','Resumo editorial de várias imagens; conferir a Resolução CONTRAN vigente.','https://www.gov.br/transportes/pt-br/assuntos/transito/conteudo-contran/resolucoes/Resolucao9962023.pdf',130)
on conflict (category,title) do nothing;
